#include <iostream>
#include <fstream>
#include <string>
#include <map>
using namespace std;

int main() {
    ifstream plik("teksty.txt");
    string s;
    map<int, int> hist;
    while (plik >> s) hist[s.length()]++;
    cout << "Histogram dlugosci slow:" << endl;
    int maxLen = 0, maxCnt = 0;
    for (auto& p : hist) {
        cout << "   Dlugosc " << p.first << ": " << p.second << endl;
        if (p.second > maxCnt) {
            maxCnt = p.second;
            maxLen = p.first;
        }
    }
    cout << "Najczestsza dlugosc: " << maxLen << " (" << maxCnt << " slow)" << endl;
    return 0;
}
```

Weryfikacja:
- Dlugosc 2: ja, to, ok, ze, do = 5
- Dlugosc 3: kot, dom, bit = 3
- Dlugosc 4: mapa = 1
- Dlugosc 8: samochod, komputer, algorytm = 3
- Dlugosc 9: struktura = 1
- Dlugosc 11: informatyka = 1
- Dlugosc 13: programowanie = 1
